sourcesContent:
﻿<script setup lang="ts">
import { computed } from 'vue'
import { SPECIFIC_HEAT_WATER, SPECIFIC_HEAT_ALUMINUM } from '../../../../composables/calorimetry/useCalorimetryCalculations'
const props = defineProps<{
  mWater: number
  tWater: number
  mMetal: number
  tMetal: number
  tf: number
  cMetal: number
}>()

const qLost = computed(() => props.mMetal * props.cMetal * (props.tMetal - props.tf))
const qGained = computed(() => (props.mWater * SPECIFIC_HEAT_WATER + 0.05 * SPECIFIC_HEAT_ALUMINUM) * (props.tf - props.tWater))
const balance = computed(() => Math.abs(qLost.value - qGained.value))
</script>
<template>
  <div class="panel-body" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:18:3">
    <div class="law-box balance" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:19:5">
      <div class="law-title" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:20:7">موازنة الطاقة الحرارية</div>
      <div class="formula" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:21:7">Q_{مفقود} = Q_{مكتسب}</div>
      <div class="data-grid" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:22:7">
        <div class="data-item" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:23:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:23:32">Q_{مفقود}</span><span class="data-val" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:23:73">{{ qLost.toFixed(1) }} J</span></div>
        <div class="data-item" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:24:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:24:32">Q_{مكتسب}</span><span class="data-val" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:24:73">{{ qGained.toFixed(1) }} J</span></div>
        <div class="data-item" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:25:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:25:32">ΔQ</span><span class="data-val" :class="balance < 1 ? 'green' : 'red'" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:25:66">{{ balance.toFixed(2) }} J</span></div>
        <div class="data-item" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:26:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:26:32">الحالة</span><span class="data-val" :class="balance < 1 ? 'green' : 'red'" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:26:70">{{ balance < 1 ? 'متوازن ✅' : 'غير متوازن' }}</span></div>
      </div>
    </div>
    <div class="law-box calc" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:29:5">
      <div class="law-title" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:30:7">حساب السعة الحرائية</div>
      <div class="formula" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:31:7">c = Q / (m · ΔT)</div>
      <div class="data-grid" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:32:7">
        <div class="data-item" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:33:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:33:32">Q</span><span class="data-val" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:33:65">{{ qGained.toFixed(1) }} J</span></div>
        <div class="data-item" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:34:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:34:32">m</span><span class="data-val" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:34:65">{{ mMetal.toFixed(3) }} kg</span></div>
        <div class="data-item" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:35:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:35:32">ΔT</span><span class="data-val" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:35:66">{{ (tMetal - tf).toFixed(1) }} °C</span></div>
        <div class="data-item highlight" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:36:9"><span class="data-label" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:36:42">c_{مقاس}</span><span class="data-val green" data-v-inspector="src/components/experiment/calorimetry/panels/CalorimetryLawsPanel.vue:36:82">{{ (qGained / (mMetal * (tMetal - tf))).toFixed(0) }} J/kg·K</span></div>
      </div>
    </div>
  </div>
</template>
<style scoped>
.panel-body { padding:.5rem; display:flex; flex-direction:column; gap:.45rem; }
.law-box { border-radius:8px; padding:.6rem .7rem; }
.law-box.balance { background:rgba(91,141,184,.06); border:1px solid rgba(91,141,184,.18); }
.law-box.calc { background:rgba(245,158,11,.06); border:1px solid rgba(245,158,11,.18); }
.law-title { font-weight:800; font-size:.8rem; margin-bottom:.4rem; }
.law-box.balance .law-title { color:#5B8DB8; }
.law-box.calc .law-title { color:#fbbf24; }
.formula { font-family:'Courier New', monospace; font-size:.9rem; color:#D1D7E0; text-align:center; margin:.25rem 0 .15rem; letter-spacing:.5px; }
.data-grid { display:flex; flex-direction:column; gap:.2rem; }
.data-item { display:flex; justify-content:space-between; padding:.25rem .35rem; border-radius:4px; background:rgba(255,255,255,.02); font-size:.74rem; }
.data-item.highlight { background:rgba(74,222,128,.08); border:1px solid rgba(74,222,128,.2); }
.data-label { color:#8B95A5; }
.data-val { color:#D1D7E0; font-weight:700; }
.data-val.green { color:#4ade80; }
.data-val.red { color:#f87171; }
</style>

